vec2 ab = b - a;
vec2 ac = c - a;
vec2 pa = a - p;
float det = ab.x * ac.y - ab.y * ac.x;
if (std::abs(det) < 1e-6) return vec3(-1, 1, 1);
float inv_det = 1.0f / det;
float u = (pa.y * ac.x - pa.x * ac.y) * inv_det;
float v = (ab.y * pa.x - ab.x * pa.y) * inv_det;
return vec3(1.0f - u - v, u, v);
// END_CODE

